import Link from "next/link";
import {
  ArrowUpRight,
  Search,
  MapPin,
  Sparkles,
  CheckCircle2,
} from "lucide-react";

export default function Home() {
  const featuredRoles = [
    {
      title: "Product Designer",
      company: "Porter",
      location: "Remote",
      type: "Full-time",
      salary: "$145k–$175k",
      mark: "P",
      markBg: "bg-indigo-500/10 text-indigo-400 border-indigo-500/20",
    },
    {
      title: "Frontend Engineer",
      company: "Morrow",
      location: "New York",
      type: "Hybrid",
      salary: "$130k–$160k",
      mark: "M",
      markBg: "bg-emerald-500/10 text-emerald-400 border-emerald-500/20",
    },
    {
      title: "Content Strategist",
      company: "Good Kind",
      location: "London",
      type: "Hybrid",
      salary: "£68k–£82k",
      mark: "G",
      markBg: "bg-amber-500/10 text-amber-400 border-amber-500/20",
    },
  ];

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 selection:bg-indigo-500 selection:text-white font-sans antialiased overflow-x-hidden">
      {/* Background Gradients */}
      <div className="fixed inset-0 -z-10 pointer-events-none">
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[1000px] h-[500px] bg-gradient-to-tr from-indigo-500/15 via-purple-500/10 to-transparent blur-3xl opacity-70" />
        <div className="absolute top-[40%] right-0 w-[500px] h-[500px] bg-sky-500/10 blur-3xl opacity-50" />
      </div>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-12 pb-24 space-y-32">
        {/* HERO SECTION */}
        <section
          className="grid lg:grid-cols-12 gap-12 lg:gap-8 items-center pt-8"
          aria-labelledby="hero-title"
        >
          <div className="lg:col-span-7 space-y-8">
            {/* Eyebrow */}
            <div className="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full bg-slate-900/80 border border-slate-800 backdrop-blur-md shadow-inner text-xs font-medium text-indigo-300">
              <span className="relative flex h-2 w-2">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-indigo-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-2 w-2 bg-indigo-500"></span>
              </span>
              The smarter way to move forward
            </div>

            {/* Title */}
            <h1
              id="hero-title"
              className="text-4xl sm:text-6xl font-extrabold tracking-tight text-white leading-[1.1]"
            >
              Find work that feels <br className="hidden sm:inline" />
              <em className="not-italic bg-gradient-to-r from-indigo-400 via-purple-300 to-pink-400 bg-clip-text text-transparent">
                like you.
              </em>
            </h1>

            {/* Description */}
            <p className="text-lg sm:text-xl text-slate-400 max-w-2xl font-normal leading-relaxed">
              Discover roles worth showing up for, then build the confidence to
              make them yours.
            </p>

            {/* Search Form */}
            <form
              className="p-2 sm:p-2.5 rounded-2xl bg-slate-900/90 border border-slate-800 shadow-2xl backdrop-blur-xl"
              action="/jobs"
              method="get"
            >
              <label htmlFor="role-search" className="sr-only">
                Search by role, skill, or company
              </label>
              <div className="flex flex-col sm:flex-row items-center gap-2">
                <div className="relative flex-1 w-full">
                  <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-500" />
                  <input
                    id="role-search"
                    name="q"
                    type="text"
                    placeholder="Role, skill, or company"
                    className="w-full pl-11 pr-4 py-3 bg-slate-950/50 rounded-xl border border-slate-800 text-sm text-slate-200 placeholder-slate-500 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all"
                  />
                </div>
                <div className="relative flex-1 w-full">
                  <MapPin className="absolute left-3.5 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-500" />
                  <input
                    name="location"
                    type="text"
                    placeholder="Anywhere (Location)"
                    className="w-full pl-11 pr-4 py-3 bg-slate-950/50 rounded-xl border border-slate-800 text-sm text-slate-200 placeholder-slate-500 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all"
                  />
                </div>
                <button
                  type="submit"
                  className="w-full sm:w-auto px-6 py-3 rounded-xl bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 text-white font-medium text-sm flex items-center justify-center gap-2 shadow-lg shadow-indigo-500/25 transition-all duration-200 active:scale-95"
                >
                  <span>Search</span>
                  <ArrowUpRight className="w-4 h-4" />
                </button>
              </div>
            </form>

            {/* Social Proof */}
            <div className="flex items-center gap-4 text-sm text-slate-400 pt-2">
              <div className="flex -space-x-2 overflow-hidden">
                <div className="inline-block h-8 w-8 rounded-full ring-2 ring-slate-950 bg-indigo-600 flex items-center justify-center text-xs font-bold text-white">
                  JD
                </div>
                <div className="inline-block h-8 w-8 rounded-full ring-2 ring-slate-950 bg-purple-600 flex items-center justify-center text-xs font-bold text-white">
                  MK
                </div>
                <div className="inline-block h-8 w-8 rounded-full ring-2 ring-slate-950 bg-slate-800 flex items-center justify-center text-xs font-bold text-indigo-400">
                  +
                </div>
              </div>
              <p>
                Join{" "}
                <strong className="text-slate-200 font-semibold">
                  12,000+
                </strong>{" "}
                people preparing for their next move.
              </p>
            </div>
          </div>

          {/* Hero Side Panel Card */}
          <div className="lg:col-span-5">
            <div className="relative rounded-3xl p-6 sm:p-8 bg-gradient-to-b from-slate-900/80 to-slate-950/80 border border-slate-800 shadow-2xl backdrop-blur-xl space-y-6">
              <div className="flex items-center justify-between text-xs font-semibold tracking-wider text-slate-400">
                <span className="uppercase">Curated for you</span>
                <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" />
                  LIVE
                </span>
              </div>

              <div className="space-y-3">
                <span className="text-xs font-bold text-indigo-400 tracking-wider uppercase">
                  Your Next Move
                </span>
                <h2 className="text-2xl sm:text-3xl font-bold text-white">
                  Good work is <br />
                  <em className="not-italic text-purple-300">out there.</em>
                </h2>
                <p className="text-sm text-slate-400">
                  Roles matched to your ambition, not just your keywords.
                </p>
              </div>

              {/* Role Preview Card */}
              <div className="group p-4 rounded-2xl bg-slate-950/60 border border-slate-800 hover:border-indigo-500/40 transition-all flex items-center justify-between gap-4 cursor-pointer">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-xl bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 font-bold flex items-center justify-center text-lg">
                    P
                  </div>
                  <div>
                    <h3 className="text-sm font-semibold text-slate-100 group-hover:text-indigo-300 transition-colors">
                      Senior Product Designer
                    </h3>
                    <p className="text-xs text-slate-400">
                      Porter · Remote · $145k–$175k
                    </p>
                  </div>
                </div>
                <ArrowUpRight className="w-5 h-5 text-slate-500 group-hover:text-indigo-400 group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-all" />
              </div>

              <div className="flex items-center justify-between text-xs text-slate-500 pt-2 border-t border-slate-800/60">
                <span>01 / 04</span>
                <span>Hand-picked opportunities</span>
              </div>
            </div>
          </div>
        </section>

        {/* STATS SECTION */}
        <section className="grid grid-cols-2 md:grid-cols-4 gap-6 p-8 rounded-3xl bg-slate-900/40 border border-slate-800/80 backdrop-blur-md">
          {[
            { value: "12k+", label: "active candidates" },
            { value: "840", label: "open opportunities" },
            { value: "4.9/5", label: "practice room rating" },
            { value: "86%", label: "feel more prepared" },
          ].map((stat, idx) => (
            <div key={idx} className="space-y-1 text-center md:text-left">
              <div className="text-3xl sm:text-4xl font-extrabold text-white tracking-tight">
                {stat.value}
              </div>
              <div className="text-xs sm:text-sm text-slate-400 capitalize">
                {stat.label}
              </div>
            </div>
          ))}
        </section>

        {/* FEATURED ROLES SECTION */}
        <section className="space-y-8" aria-labelledby="featured-title">
          <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4">
            <div>
              <p className="text-xs font-semibold tracking-wider text-indigo-400 uppercase">
                01 / Opportunities
              </p>
              <h2
                id="featured-title"
                className="text-3xl sm:text-4xl font-bold text-white tracking-tight mt-1"
              >
                Roles with{" "}
                <em className="not-italic text-purple-300">range.</em>
              </h2>
            </div>
            <Link
              className="inline-flex items-center gap-1 text-sm font-medium text-indigo-400 hover:text-indigo-300 transition-colors group"
              href="/jobs"
            >
              Browse all roles
              <ArrowUpRight className="w-4 h-4 group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-transform" />
            </Link>
          </div>

          <div className="grid md:grid-cols-3 gap-6">
            {featuredRoles.map((role, index) => (
              <Link
                key={role.title}
                href="/jobs"
                className="group relative p-6 rounded-2xl bg-slate-900/50 border border-slate-800 hover:border-slate-700 hover:bg-slate-900/80 transition-all flex flex-col justify-between space-y-6"
              >
                <div className="flex items-center justify-between">
                  <div
                    className={`w-10 h-10 rounded-xl border flex items-center justify-center font-bold ${role.markBg}`}
                  >
                    {role.mark}
                  </div>
                  <span className="text-xs font-mono text-slate-500">
                    0{index + 1}
                  </span>
                </div>

                <div className="space-y-1">
                  <h3 className="text-lg font-semibold text-slate-100 group-hover:text-indigo-300 transition-colors">
                    {role.title}
                  </h3>
                  <p className="text-sm text-slate-400">{role.company}</p>
                </div>

                <div className="pt-4 border-t border-slate-800/80 flex items-center justify-between text-xs text-slate-400">
                  <span>
                    {role.location} · {role.type}
                  </span>
                  <strong className="text-slate-200 font-semibold">
                    {role.salary}
                  </strong>
                </div>

                <div className="absolute top-6 right-6 opacity-0 group-hover:opacity-100 transition-opacity">
                  <ArrowUpRight className="w-5 h-5 text-indigo-400" />
                </div>
              </Link>
            ))}
          </div>
        </section>

        {/* PRACTICE BANNER */}
        <section className="relative overflow-hidden rounded-3xl bg-gradient-to-b from-indigo-950/40 to-slate-900/80 border border-indigo-500/20 p-8 sm:p-12 grid lg:grid-cols-12 gap-12 items-center">
          <div className="lg:col-span-7 space-y-6">
            <p className="text-xs font-semibold tracking-wider text-indigo-400 uppercase">
              02 / Your unfair advantage
            </p>
            <h2 className="text-3xl sm:text-5xl font-extrabold text-white tracking-tight leading-tight">
              A better interview <br />
              <em className="not-italic text-purple-300">starts before it.</em>
            </h2>
            <p className="text-base sm:text-lg text-slate-300 leading-relaxed max-w-xl">
              Turn job descriptions into focused practice. Our AI interviewer
              helps you find the words, sharpen your story, and walk in ready.
            </p>
            <Link
              className="inline-flex items-center gap-2 px-6 py-3.5 rounded-xl bg-white hover:bg-slate-100 text-slate-950 font-semibold text-sm shadow-xl transition-all hover:scale-[1.02] active:scale-95"
              href="/interviews"
            >
              <span>Practice for a role</span>
              <ArrowUpRight className="w-4 h-4" />
            </Link>
          </div>

          <div className="lg:col-span-5 space-y-4">
            {[
              { step: "01", text: "Paste a job description" },
              { step: "02", text: "Practice the real questions" },
              { step: "03", text: "Show up as yourself" },
            ].map((s) => (
              <div
                key={s.step}
                className="flex items-center gap-4 p-4 rounded-xl bg-slate-900/80 border border-slate-800/80"
              >
                <span className="flex items-center justify-center w-8 h-8 rounded-lg bg-indigo-500/10 text-indigo-400 text-xs font-mono font-bold">
                  {s.step}
                </span>
                <strong className="text-sm font-medium text-slate-200">
                  {s.text}
                </strong>
              </div>
            ))}
          </div>
        </section>

        {/* CALL TO ACTION */}
        <section className="text-center py-12 space-y-8">
          <p className="text-xs font-semibold tracking-wider text-indigo-400 uppercase">
            Ready when you are
          </p>
          <h2 className="text-4xl sm:text-6xl font-extrabold text-white tracking-tight leading-tight">
            The next chapter <br />
            <em className="not-italic text-purple-300">has your name on it.</em>
          </h2>
          <div className="flex justify-center pt-4">
            <Link
              className="group flex items-center justify-center w-16 h-16 rounded-full bg-gradient-to-tr from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 text-white shadow-xl shadow-indigo-500/25 transition-all hover:scale-110 active:scale-95"
              href="/jobs"
              aria-label="Explore jobs"
            >
              <ArrowUpRight className="w-8 h-8 group-hover:rotate-45 transition-transform duration-300" />
            </Link>
          </div>
        </section>
      </main>
    </div>
  );
}
